  function record(event,payload={}){if(!EVENTS.includes(event)||!plain(payload))return false;const rawAmount=own(payload,'amount');if(rawAmount!==undefined&&(!Number.isFinite(rawAmount)||rawAmount<=0||!Number.isInteger(rawAmount)))return false;const amount=rawAmount===undefined?1:Math.min(50,rawAmount),uid=text(own(payload,'eventId'));if(uid&&state.recentEventIds.includes(uid))return false;if(uid){state.recentEventIds.push(uid);state.recentEventIds=state.recentEventIds.slice(-160);}state.sequence=Math.min(MAX_SEQUENCE,state.sequence+1);let dirty=false;for(const def of arcs){const r=row(def);if(r.status!=='active'||r.acceptedAt===null||state.sequence<=r.acceptedAt)continue;for(const g of currentStage(def,r).objectives){if(g.event!==event||!Object.entries(g.match).every(([key,value])=>own(payload,key)===value))continue;const before=num(r.counts[g.id],g.goal);r.counts[g.id]=Math.min(g.goal,before+amount);dirty=dirty||r.counts[g.id]!==before;}if(complete(def,r)){r.status='ready';dirty=true;}}if(dirty)changed();return dirty;}
